import{_ as t,c as a,o as r,a2 as i}from"./chunks/framework.ZL09jyt0.js";const o="/pr-preview/pr-811/assets/2025-12.C-sEi27e.jpg",p=JSON.parse('{"title":"December 2025","description":"","frontmatter":{"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/community/hackathons","outline":2,"params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/community/hackathons/2025-12.md","to":"2025-12.md"},"title":"December 2025","weight":-202512,"prev":false,"next":false},"headers":[],"relativePath":"community/hackathons/2025-12/index.md","filePath":"community/hackathons/2025-12.md","lastUpdated":null}'),n={name:"community/hackathons/2025-12/index.md"};function s(l,e,h,c,d,m){return r(),a("div",null,e[0]||(e[0]=[i('<h1 id="hack-the-garden-12-2025-wrap-up" tabindex="-1">Hack The Garden 12/2025 Wrap Up <a class="header-anchor" href="#hack-the-garden-12-2025-wrap-up" aria-label="Permalink to &quot;Hack The Garden 12/2025 Wrap Up&quot;">​</a></h1><ul><li>🗓️ <strong>Date:</strong> 08.12.2025 – 12.12.2025</li><li>📍 <strong>Location:</strong> SAP Center Walldorf</li><li>👤 <strong>Organizer:</strong> SAP</li></ul><p><img src="'+o+'" alt="Group picture"></p><h2 id="⚙️-oidc-webhook-garden-class-extension" tabindex="-1">⚙️ OIDC Webhook Garden Class Extension <a class="header-anchor" href="#⚙️-oidc-webhook-garden-class-extension" aria-label="Permalink to &quot;⚙️ OIDC Webhook Garden Class Extension&quot;">​</a></h2><h3 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Install OIDC in the garden cluster as a Garden class extension to enable proper authentication mechanisms.</p><h3 id="motivation-benefits" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Enable OIDC authentication for the garden cluster through a proper extension mechanism, improving security and authentication capabilities.</p><h3 id="achievements" tabindex="-1">Achievements <a class="header-anchor" href="#achievements" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>Extensions were adapted to manage Garden class extensions.</li><li>Successfully installed the OIDC Webhook Authenticator for the garden cluster.</li><li>Identified several gaps in Gardener with respect to Garden Extensions: <ul><li>Garden namespace is not labelled with <code>extension-type: true</code> label, so admission webhooks namespace selector does not work.</li><li><code>EnsureKubeAPIServer</code> handler needs to add support for deployments named <code>virtual-garden-kube-apiserver</code>.</li><li>Health Check controller needs preparation for garden use-case.</li><li>SecretsManager utility needs to create a manager from the garden resource.</li><li>Need to avoid collisions when a runtime cluster is also a seed and has multiple extension controllers working on the same resource.</li></ul></li></ul><h3 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Finalize changes in the extension (mainly adapt tests).</li></ul><h3 id="code-pull-requests" tabindex="-1">Code &amp; Pull Requests <a class="header-anchor" href="#code-pull-requests" aria-label="Permalink to &quot;Code &amp; Pull Requests&quot;">​</a></h3><ul><li><a href="https://github.com/gardener/gardener/pull/13635" target="_blank" rel="noreferrer">gardener/gardener#13635</a></li><li><a href="https://github.com/gardener/gardener/pull/13662" target="_blank" rel="noreferrer">gardener/gardener#13662</a></li></ul><h2 id="🔍-use-dummy-rbac-resources-verb-to-identify-dod-sre-and-auditor" tabindex="-1">🔍 Use Dummy RBAC Resources+Verb to Identify DoD/SRE and Auditor <a class="header-anchor" href="#🔍-use-dummy-rbac-resources-verb-to-identify-dod-sre-and-auditor" aria-label="Permalink to &quot;🔍 Use Dummy RBAC Resources+Verb to Identify DoD/SRE and Auditor&quot;">​</a></h2><h3 id="problem-statement-1" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-1" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Dashboard &amp; Gardener APIServer rely on RBAC to determine your role (e.g., admin). This must replace the checks for &quot;Can I list all secrets&quot; and &quot;Can I list all Projects&quot;.</p><h3 id="motivation-benefits-1" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-1" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Improve RBAC-based role detection by using dedicated dummy resources and verbs instead of relying on permission checks for sensitive resources, like secrets and projects.</p><h3 id="achievements-1" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-1" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>The topic was explored and the problem statement was defined.</li><li>A proposition for a solution that will improve the current state was developed.</li></ul><h3 id="next-steps-1" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-1" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Wait for input by the community on the best approach.</li></ul><h3 id="code-pull-requests-1" tabindex="-1">Code &amp; Pull Requests <a class="header-anchor" href="#code-pull-requests-1" aria-label="Permalink to &quot;Code &amp; Pull Requests&quot;">​</a></h3><ul><li>Issue: <a href="https://github.com/gardener/gardener/issues/13657" target="_blank" rel="noreferrer">gardener/gardener#13657</a></li><li>Proposed solution: <a href="https://github.com/dimityrmirchev/gardener/tree/virtualrbac" target="_blank" rel="noreferrer">dimityrmirchev/gardener:virtualrbac</a></li></ul><h2 id="🔒-private-api-servers" tabindex="-1">🔒 Private API Servers <a class="header-anchor" href="#🔒-private-api-servers" aria-label="Permalink to &quot;🔒 Private API Servers&quot;">​</a></h2><h3 id="problem-statement-2" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-2" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Gardener exposes API servers of shoot clusters to the internet on all infrastructures except for SAP Cloud Infrastructure, where this is only opt-in. While it is very convenient to be able to reach the API server from everywhere, it has security implications by making it easier for malicious actors to attack the API server.</p><h3 id="motivation-benefits-2" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-2" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>With technical features like private link or private service connect, it should be possible to provide private API servers to shoot clusters, reducing the attack surface for security conscious stakeholders.</p><h3 id="achievements-2" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-2" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><p>Work in progress on implementing private API server support.</p><h3 id="next-steps-2" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-2" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><p>Continue implementation and testing of private API server functionality.</p><h2 id="🔐-use-github-oidc-federation-to-get-rid-of-github-apps-again" tabindex="-1">🔐 Use GitHub OIDC Federation to Get Rid of GitHub Apps (Again) <a class="header-anchor" href="#🔐-use-github-oidc-federation-to-get-rid-of-github-apps-again" aria-label="Permalink to &quot;🔐 Use GitHub OIDC Federation to Get Rid of GitHub Apps (Again)&quot;">​</a></h2><h3 id="problem-statement-3" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-3" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>GHA-Pipelines can make use of trust-based-authentication (for Gardener-CICD, we already do this for shoot clusters and hyperscalers). However, there is no built-in support for access to either other GitHub-(Enterprise)-Instances, or even cross-repository/cross-organisation-access.</p><h3 id="motivation-benefits-3" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-3" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Eliminate the need for GitHub-Apps for cross-github-authentication by leveraging OIDC federation, improving security, and reducing maintenance overhead.</p><h3 id="achievements-3" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-3" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>Explored existing PoCs from OSPO and Chainguard&#39;s Secure Token Service (<a href="https://github.com/octo-sts" target="_blank" rel="noreferrer">octo-sts</a>).</li><li>Evaluated the feasibility of setting up a custom instance with an internet-facing token-exchange-endpoint.</li></ul><h3 id="next-steps-3" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-3" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Set up a custom instance, including support for github.wdf.sap.corp.</li><li>Complete implementation, with the ultimate goal of eliminating GitHub-Apps usage for cross-github-authentication.</li></ul><h3 id="code-pull-requests-2" tabindex="-1">Code &amp; Pull Requests <a class="header-anchor" href="#code-pull-requests-2" aria-label="Permalink to &quot;Code &amp; Pull Requests&quot;">​</a></h3><ul><li>Chainguard STS: <a href="https://github.com/apps/octo-sts" target="_blank" rel="noreferrer">github.com/apps/octo-sts</a></li><li>Source code: <a href="https://github.com/octo-sts" target="_blank" rel="noreferrer">github.com/octo-sts</a></li></ul><h2 id="✅-provide-validation-job-of-kyverno-policies-without-kyverno" tabindex="-1">✅ Provide Validation Job of Kyverno Policies Without Kyverno <a class="header-anchor" href="#✅-provide-validation-job-of-kyverno-policies-without-kyverno" aria-label="Permalink to &quot;✅ Provide Validation Job of Kyverno Policies Without Kyverno&quot;">​</a></h2><h3 id="problem-statement-4" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-4" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>It is generally agreed that validating Kubernetes resources based on common policies is a good health measure for Kubernetes deployments and increases security. Today&#39;s options are limited: Kyverno provides this functionality but can be problematic for cluster health and requires significant effort to implement. Kubernetes admission policies are only applicable to newly deployed resources, not existing ones.</p><h3 id="motivation-benefits-4" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-4" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Have lightweight jobs that regularly check all resources in the cluster and report violations based on common (Kyverno) policies, without requiring a full Kyverno installation.</p><h3 id="achievements-4" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-4" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>Validated that the Kyverno CLI can verify policies against a target cluster with some limitations (e.g., it cannot check CRDs).</li><li>Identified CLI deficiencies: <ul><li>The report command does not produce valid YAML but includes free text, requiring special parsing.</li><li>The command returns an error on policy violations, making it hard to distinguish between command errors and failing policies.</li></ul></li><li>Created a PoC integration of the Kyverno CLI into DIKI.</li></ul><h3 id="next-steps-4" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-4" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Address the identified CLI limitations.</li><li>Complete the integration into DIKI and prepare for production use.</li></ul><h3 id="code-pull-requests-3" tabindex="-1">Code &amp; Pull Requests <a class="header-anchor" href="#code-pull-requests-3" aria-label="Permalink to &quot;Code &amp; Pull Requests&quot;">​</a></h3><ul><li>PoC branch: <a href="https://github.com/dimityrmirchev/diki/tree/kyverno-ruleset-poc" target="_blank" rel="noreferrer">dimityrmirchev/diki:kyverno-ruleset-poc</a></li></ul><h2 id="📡-observability-signals-externalization" tabindex="-1">📡 Observability Signals Externalization <a class="header-anchor" href="#📡-observability-signals-externalization" aria-label="Permalink to &quot;📡 Observability Signals Externalization&quot;">​</a></h2><h3 id="problem-statement-5" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-5" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Currently, observability signals (logs and metrics) for clients are persisted in the shoot control-plane namespace of the shoot clusters running in the seed. GEP-34 laid down the foundations of OpenTelemetry support in Gardener, making it possible for signals to be collected and processed by OpenTelemetry collectors. However, the observability signals we persist still have a fixed retention policy, over which clients don&#39;t have any control.</p><h3 id="motivation-benefits-5" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-5" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Allowing control-plane signals such as metrics and logs to be forwarded and persisted by cluster owners to their own OpenTelemetry-aware endpoint would let clients configure and manage their own retention policies.</p><h3 id="achievements-5" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-5" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>OTel extension is in a functional state with local setup ready.</li><li>ServiceMonitors from shoot control-plane namespace are being discovered by Target Allocator (TA) and scraped by the Collector.</li><li>Implemented authentication between the OTel exporter and remote OTel receiver.</li><li>Implemented mTLS using Gardener secrets manager between Target Allocator and Collector.</li><li>Defined Extension API.</li></ul><h3 id="next-steps-5" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-5" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Polish the implementation (complete TODO items, clean up the API).</li><li>Increase test coverage.</li><li>Add support for shipping signals to an OTLP gRPC endpoint.</li><li>Add support for shipping logs.</li><li>Follow up on upstream issues related to mTLS.</li></ul><h2 id="🛰️-perses-dashboards-explore-plugin" tabindex="-1">🛰️ Perses Dashboards &amp; Explore Plugin <a class="header-anchor" href="#🛰️-perses-dashboards-explore-plugin" aria-label="Permalink to &quot;🛰️ Perses Dashboards &amp; Explore Plugin&quot;">​</a></h2><h3 id="problem-statement-6" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-6" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Version <a href="https://github.com/perses/perses/releases/tag/v0.53.0-beta.2" target="_blank" rel="noreferrer">0.53.0-beta2</a> of Perses now supports VictoriaLogs as a data source, aligning with <a href="https://github.com/gardener/gardener/pull/13242" target="_blank" rel="noreferrer">GEP-35</a> where VictoriaLogs will replace Vali as the backend of logs from all clusters. <a href="https://github.com/credativ/plutono" target="_blank" rel="noreferrer">Plutono</a> is the current UI for displaying metrics from Prometheus and Vali, but we&#39;re aiming at replacing it in the same timeframe as Vali. However, feature parity is not there yet because Perses does not have an explore plugin for logs yet.</p><h3 id="motivation-benefits-6" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-6" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Achieve a full replacement of Plutono with Perses, including configuration with Prometheus and VictoriaLogs as data sources, migrating all dashboards, and achieving full feature parity with the current solution.</p><h3 id="achievements-6" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-6" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>Evaluated what would be needed to achieve a full replacement of Plutono with Perses.</li><li>Explored existing plugins (prometheus, pyroscope, and tempo) that can be used as a frame of reference for a Log Explorer plugin.</li><li>Identified operator shortcomings that need to be addressed.</li></ul><h3 id="next-steps-6" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-6" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Contribute the Log Explorer plugin to remove one of the roadblocks on the way to replacing Plutono.</li><li>Address operator shortcomings: <ul><li>Add <code>emptyDir</code> support to avoid reliance on PersistentVolumes for config files.</li><li>Find solutions for creating global datasources needed for explore mode.</li></ul></li><li>Complete dashboard migration and feature parity assessment.</li></ul><h2 id="🔭-gardener-opentelemetry-receiver" tabindex="-1">🔭 Gardener OpenTelemetry Receiver <a class="header-anchor" href="#🔭-gardener-opentelemetry-receiver" aria-label="Permalink to &quot;🔭 Gardener OpenTelemetry Receiver&quot;">​</a></h2><h3 id="problem-statement-7" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-7" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>The gardener-metrics-exporter provides information about the condition of Shoots, Seeds, and other Gardener resources in the Prometheus metric format. There is an ongoing initiative to replace gardener-metrics-exporter with kube-state-metrics and its custom resource state monitoring feature to avoid maintaining a custom exporter. The OpenTelemetry Collector introduced a receiver concept, which is an alternative to Prometheus exporters and can provide OTLP metrics without any conversions.</p><h3 id="motivation-benefits-7" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-7" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Develop a custom receiver for the OpenTelemetry Collector that provides similar information as the gardener-metrics-exporter and evaluate if our planned migration to kube-state-metrics is still the right choice with our Observability 2.0 strategy. The custom receiver could be used by stakeholders to monitor the condition of their Shoots and ingest the metrics into a managed backend like Dynatrace or the BTP Cloud Logging Service, requiring only a (lightweight) OpenTelemetry Collector instead of a full Prometheus instance.</p><h3 id="achievements-7" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-7" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>Implemented OTel receiver <a href="https://github.com/chrkl/gardener-opentelemetry-collector/tree/gardener-receiver" target="_blank" rel="noreferrer">prototype</a> by following the tutorials from the OTel community for <a href="https://opentelemetry.io/docs/collector/building/receiver/" target="_blank" rel="noreferrer">building a receiver</a> and <a href="https://opentelemetry.io/docs/collector/custom-collector/" target="_blank" rel="noreferrer">building a custom collector</a>.</li><li>Emitting metrics with shoot and seed information.</li><li>Demo setup to push Gardener metrics to Prometheus using its OTLP API.</li></ul><h3 id="next-steps-7" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-7" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Align within the monitoring team on whether to continue with this approach.</li><li>Add missing metrics to reach feature parity with gardener-metrics-exporter.</li><li>Re-think the metric modeling to follow best practices of the OTel ecosystem.</li><li>Bring the prototype into a proper shape (e.g., proper use of k8s client with informers, adding tests, update to latest collector dependencies).</li></ul><h2 id="🔄-poc-replace-prometheus-exporters-by-opentelemetry-receivers-in-gardener-monitoring-stack" tabindex="-1">🔄 PoC: Replace Prometheus Exporters by OpenTelemetry Receivers in Gardener Monitoring Stack <a class="header-anchor" href="#🔄-poc-replace-prometheus-exporters-by-opentelemetry-receivers-in-gardener-monitoring-stack" aria-label="Permalink to &quot;🔄 PoC: Replace Prometheus Exporters by OpenTelemetry Receivers in Gardener Monitoring Stack&quot;">​</a></h2><h3 id="problem-statement-8" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-8" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>The Gardener monitoring stack uses various upstream Prometheus exporters to collect typical metrics of a Kubernetes cluster, including node_exporter, kube-state-metrics, and cAdvisor. The OpenTelemetry project introduced the receiver concept in the Collector component to gather telemetry data. The opentelemetry-collector-contrib GitHub repository already contains multiple receivers that serve a similar purpose as the mentioned Prometheus exporters.</p><h3 id="motivation-benefits-8" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-8" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Build a PoC setup purely based on native OpenTelemetry components to monitor a Kubernetes cluster and gather experience about the best telemetry data sources when implementing the Observability 2.0 strategy.</p><h3 id="achievements-8" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-8" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>Results: <a href="https://hackmd.io/@DyOu5KAIQCK5iNWapbO6sg/r1y0zH9NZe" target="_blank" rel="noreferrer">HackMD</a></li></ul><h3 id="next-steps-8" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-8" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Identify potential gaps in the metrics provided by the OpenTelemetry receivers.</li><li>Complete the comparison and document findings.</li><li>Decide on the adoption strategy for Observability 2.0.</li></ul><h2 id="🔕-poc-investigate-alertmanager-silence-operator" tabindex="-1">🔕 PoC: Investigate Alertmanager Silence-Operator <a class="header-anchor" href="#🔕-poc-investigate-alertmanager-silence-operator" aria-label="Permalink to &quot;🔕 PoC: Investigate Alertmanager Silence-Operator&quot;">​</a></h2><h3 id="problem-statement-9" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-9" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Investigate the operational cost benefit of eliminating alertmanager silence PVs and assess if it&#39;s worth introducing the silence operator for alertmanager.</p><h3 id="motivation-benefits-9" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-9" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Reduce operational costs and complexity by potentially eliminating the need for PersistentVolumes for alertmanager silences.</p><h3 id="achievements-9" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-9" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>Results: <a href="https://hackmd.io/6_CbsnAuT5qh9wwz70k5gw" target="_blank" rel="noreferrer">HackMD</a></li></ul><h3 id="next-steps-9" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-9" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Review findings with the team.</li><li>Decide on adoption strategy based on cost-benefit analysis.</li></ul><h2 id="🔀-poc-investigate-opentelemetry-as-replacement-for-federation-to-garden-from-aggregate-prometheus" tabindex="-1">🔀 PoC: Investigate OpenTelemetry as Replacement for Federation to Garden from Aggregate Prometheus <a class="header-anchor" href="#🔀-poc-investigate-opentelemetry-as-replacement-for-federation-to-garden-from-aggregate-prometheus" aria-label="Permalink to &quot;🔀 PoC: Investigate OpenTelemetry as Replacement for Federation to Garden from Aggregate Prometheus&quot;">​</a></h2><h3 id="problem-statement-10" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement-10" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Current federation from aggregate to garden Prometheus requires access from the runtime cluster to seeds. Typically in Gardener, the connection originates from seeds to the runtime cluster. This creates an undesired communication direction.</p><h3 id="motivation-benefits-10" tabindex="-1">Motivation &amp; Benefits <a class="header-anchor" href="#motivation-benefits-10" aria-label="Permalink to &quot;Motivation &amp; Benefits&quot;">​</a></h3><p>Assess the feasibility of replacing current federation by using OpenTelemetry to push metrics into the garden Prometheus, effectively turning the communication direction around. Also compare this approach to using Prometheus native remote write.</p><h3 id="achievements-10" tabindex="-1">Achievements <a class="header-anchor" href="#achievements-10" aria-label="Permalink to &quot;Achievements&quot;">​</a></h3><ul><li>Results: <a href="https://hackmd.io/Yth83WkZSkqGcE_8PToKog?view" target="_blank" rel="noreferrer">HackMD</a></li></ul><h3 id="next-steps-10" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps-10" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h3><ul><li>Review findings with the team.</li><li>Decide on the implementation approach based on the comparison.</li><li>Plan migration strategy if approach is adopted.</li></ul>',110)]))}const b=t(n,[["render",s]]);export{p as __pageData,b as default};
